import { useState } from 'react';
import clsx from 'clsx';
import './AcidToggleGroup.css';

export interface AcidToggleGroupItem {
    value: string;
    label: React.ReactNode;
    disabled?: boolean;
}

export interface AcidToggleGroupProps {
    items: AcidToggleGroupItem[];
    value?: string | string[];
    defaultValue?: string | string[];
    type?: 'single' | 'multiple';
    onChange?: (value: string | string[]) => void;
    variant?: 'default' | 'outline';
    size?: 'sm' | 'md' | 'lg';
    className?: string;
}

export const AcidToggleGroup = ({
    items,
    value,
    defaultValue,
    type = 'single',
    onChange,
    variant = 'default',
    size = 'md',
    className
}: AcidToggleGroupProps) => {
    const getDefault = () => {
        if (defaultValue !== undefined) return defaultValue;
        return type === 'multiple' ? [] : '';
    };

    const [internalValue, setInternalValue] = useState<string | string[]>(getDefault());
    const selected = value !== undefined ? value : internalValue;

    const isSelected = (val: string) => {
        if (type === 'multiple') return (selected as string[]).includes(val);
        return selected === val;
    };

    const handleToggle = (val: string) => {
        let next: string | string[];
        if (type === 'multiple') {
            const arr = selected as string[];
            next = arr.includes(val) ? arr.filter(v => v !== val) : [...arr, val];
        } else {
            next = selected === val ? '' : val;
        }
        setInternalValue(next);
        onChange?.(next);
    };

    return (
        <div className={clsx('ac-toggle-group', `ac-toggle-group-${variant}`, `ac-toggle-group-${size}`, className)}>
            {items.map((item) => (
                <button
                    key={item.value}
                    className={clsx(
                        'ac-toggle-group-item',
                        isSelected(item.value) && 'ac-toggle-group-selected',
                        item.disabled && 'ac-toggle-group-item-disabled'
                    )}
                    onClick={() => !item.disabled && handleToggle(item.value)}
                    aria-pressed={isSelected(item.value)}
                    disabled={item.disabled}
                >
                    {item.label}
                </button>
            ))}
        </div>
    );
};

.ac-toggle-group {
    display: inline-flex;
    border: 1px solid var(--ac-border-muted);
    overflow: hidden;
}

.ac-toggle-group-item {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    background: transparent;
    border: none;
    border-right: 1px solid var(--ac-border-muted);
    color: var(--ac-text-secondary);
    font-family: var(--font-mono);
    font-weight: 500;
    cursor: pointer;
    transition: all 0.15s ease;
    letter-spacing: 0.04em;
}

.ac-toggle-group-sm .ac-toggle-group-item {
    padding: 0.3rem 0.65rem;
    font-size: 0.75rem;
}

.ac-toggle-group-md .ac-toggle-group-item {
    padding: 0.5rem 1.1rem;
    font-size: 0.85rem;
}

.ac-toggle-group-lg .ac-toggle-group-item {
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
}

.ac-toggle-group-item:last-child {
    border-right: none;
}

.ac-toggle-group-item:hover {
    background: var(--ac-surface-hover);
    color: var(--ac-text-primary);
}

.ac-toggle-group-selected {
    background: var(--ac-text-primary) !important;
    color: var(--ac-bg) !important;
}

.ac-toggle-group-outline .ac-toggle-group-selected {
    background: var(--ac-brand) !important;
    color: #fff !important;
    border-color: var(--ac-brand);
}

.ac-toggle-group-item-disabled {
    opacity: 0.35;
    cursor: not-allowed;
}
